/// All money is kept in hundredths of G during a calculation, so the whole-G
/// rounding happens exactly once, at the very end.
const CENTS: i64 = 100;

pub struct Item {
    pub kind: String,
}

fn base_premium(kind: &str) -> i64 {
    match kind {
        "sword" => 100,
        "amulet" => 60,
        "staff" => 80,
        "potion" => 40,
        _ => 0,
    }
}

fn round_up(cents: i64) -> i64 {
    cents.div_euclid(CENTS) + i64::from(cents.rem_euclid(CENTS) != 0)
}

pub fn quote_premium(_years: u32, _prior_contracts: u32, items: &[Item]) -> i64 {
    let policy_base: i64 = items.iter().map(|i| base_premium(&i.kind) * CENTS).sum();
    let mut total = policy_base;
    total += policy_base / 10;
    round_up(total) + 5
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(kind: &str) -> Item {
        Item { kind: kind.to_string() }
    }

    #[test]
    fn empty_item_list_costs_only_the_processing_fee() {
        assert_eq!(quote_premium(0, 0, &[]), 5);
    }

    #[test]
    fn plain_item_base_premiums_follow_the_price_list() {
        // fee 5 + first-insurance surcharge 10% of base
        assert_eq!(quote_premium(0, 0, &[item("sword")]), 115);
        assert_eq!(quote_premium(0, 0, &[item("amulet")]), 71);
        assert_eq!(quote_premium(0, 0, &[item("staff")]), 93);
        assert_eq!(quote_premium(0, 0, &[item("potion")]), 49);
    }
}
EOF
